local total = 0
for id, definition in pairs(kenney) do
    -- Protect manually authored definitions if server addons ever reuse an ID.
    if Building.Pieces[id] == nil then
        Building.Pieces[id] = definition
        total = total + 1
    end
end
if IsDuplicityVersion() then
    print(('[ALPHA-Z Kenney] %d/%d Bauteile in F2/F10 registriert.'):format(total, 80))
end
